"""Original tables, charts and qualitative probability tasks."""
from common import L, task, number, choice, multi, manual, cells, figure, error


def event_part(id, de, en, correct, skill):
    return choice(id, de, en,
                  [("certain", "sicher", "certain"),
                   ("possible", "möglich, aber nicht sicher", "possible, but not certain"),
                   ("impossible", "unmöglich", "impossible")], correct, skill)


