    def add(skill, slug, de, en, prompt_de, prompt_en, parts, use, hints,
            solution, level=2, fig=None, seconds=95):
        out.append(task(skill, slug, "data", de, en, prompt_de, prompt_en,
                        parts, use=use, hints=hints, solution=solution,
                        level=level, fig=fig, seconds=seconds))

    s = "M-D01"
